240: func (s *llamaServerRunner) completionPrompt(prompt, leadingBOS string) string {
241: 	if s.tokenizerAddsBOS() {
242: 		if leadingBOS != "" && strings.HasPrefix(prompt, leadingBOS) {
243: 			return strings.TrimPrefix(prompt, leadingBOS)
244: 		}
245: 
246: 		if strings.HasPrefix(prompt, "<bos>") {
247: 			return strings.TrimPrefix(prompt, "<bos>")
248: 		}
249: 	}
250: 
251: 	return prompt
252: }
