254: func (s *llamaServerRunner) tokenizerAddsBOS() bool {
255: 	if s.ggml == nil {
256: 		return false
257: 	}
258: 
259: 	kv := s.ggml.KV()
260: 
261: 	if kv.String("tokenizer.ggml.pre") == "lfm2" {
262: 		return true
263: 	}
264: 
265: 	// llama.cpp forces add_bos on for Gemma4 at load time, even for GGUFs
266: 	// whose tokenizer.ggml.add_bos_token metadata is explicitly false. Some
267: 	// GGUFs omit tokenizer.ggml.pre and are still treated as Gemma4 from
268: 	// tokenizer.ggml.model.
269: 	if kv.String("tokenizer.ggml.pre") == "gemma4" || kv.String("tokenizer.ggml.model") == "gemma4" {
270: 		return true
271: 	}
272: 
273: 	return kv.Bool("tokenizer.ggml.add_bos_token")
274: }
